#include <moe_topk/protocol_i_transport.h>
#include <poll.h>
#include <unistd.h>
#include <cerrno>
#include <stdexcept>
namespace moe_topk {namespace{struct H{std::uint32_t magic,n,k,len;std::uint64_t session,fp,seq;std::uint8_t bits,s,r,p,t;};constexpr std::uint32_t M=0x4d325446,MAX=1<<20;}ProtocolIFramedChannel::ProtocolIFramedChannel(int fd,ProtocolIFrameConfig c,int timeout):fd_(fd),timeout_(timeout),c_(c){if(fd<0||timeout<=0||c.bits<34||c.bits>53)throw std::invalid_argument("frame config");}ProtocolIFramedChannel::~ProtocolIFramedChannel(){if(fd_>=0)::close(fd_);}void ProtocolIFramedChannel::exact(void*p,size_t n,bool w){auto*q=(char*)p;while(n){pollfd f{fd_,(short)(w?POLLOUT:POLLIN),0};if(::poll(&f,1,timeout_)<=0)throw std::runtime_error("frame timeout");auto r=w ? ::write(fd_,q,n) : ::read(fd_,q,n);if(r<=0){if(r<0&&errno==EINTR)continue;throw std::runtime_error("frame EOF");}if(w)sent_+=r;else received_+=r;q+=r;n-=r;}}void ProtocolIFramedChannel::send(const std::vector<std::uint8_t>&x){if(x.size()>MAX)throw std::invalid_argument("frame length");H h{M,c_.n,c_.k,(std::uint32_t)x.size(),c_.session,c_.fingerprint,out_++,c_.bits,c_.sender,c_.receiver,c_.phase,c_.type};exact(&h,sizeof h,true);if(!x.empty())exact((void*)x.data(),x.size(),true);}std::vector<std::uint8_t> ProtocolIFramedChannel::receive(){H h{};exact(&h,sizeof h,false);if(h.magic!=M||h.n!=c_.n||h.k!=c_.k||h.session!=c_.session||h.fp!=c_.fingerprint||h.seq!=in_++||h.bits!=c_.bits||h.s!=c_.receiver||h.r!=c_.sender||h.p!=c_.phase||h.t!=c_.type||h.len>MAX)throw std::runtime_error("frame header");std::vector<std::uint8_t>x(h.len);if(h.len)exact(x.data(),x.size(),false);return x;}}
